//! Who owns a file Orq may see in a project: Orq never deletes, moves or
//! rewrites what the project or the TDD/MCP tooling owns.

use std::path::{Component, Path};

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum Ownership {
    /// Defined by the project (`.tdd-features.json`).
    Project,
    /// Generated by the TDD or project MCP servers.
    Mcp,
    /// Not a known tool file.
    Unowned,
}

const MCP_FILES: [&str; 3] = [".mcp.json", ".project-mcp", ".mcpctl"];
const MCP_PREFIXES: [&str; 2] = [".tdd-", ".mcpctl"];

/// Classifies a file by its name alone.
pub fn classify(name: &str) -> Ownership {
    if name == ".tdd-features.json" {
        return Ownership::Project;
    }
    if MCP_FILES.contains(&name) || MCP_PREFIXES.iter().any(|prefix| name.starts_with(prefix)) {
        return Ownership::Mcp;
    }
    Ownership::Unowned
}

/// Whether a generic Orq cleanup may delete `path`. Being unrecognised is not
/// ownership: the path must lie inside `orq_root` (lexically, with no `..`),
/// must not be the root itself, and must not be a project or MCP file.
pub fn may_orq_delete(orq_root: &Path, path: &Path) -> bool {
    let Ok(inside) = path.strip_prefix(orq_root) else { return false };
    if inside.as_os_str().is_empty() || inside.components().any(|c| !matches!(c, Component::Normal(_))) {
        return false;
    }
    if !path.file_name().and_then(|name| name.to_str()).is_some_and(|name| classify(name) == Ownership::Unowned) {
        return false;
    }
    // A symlinked directory between the root and the file would redirect the
    // deletion outside the root, so no existing ancestor may be a symlink.
    let mut ancestor = orq_root.to_path_buf();
    let parts: Vec<_> = inside.components().collect();
    for part in &parts[..parts.len() - 1] {
        ancestor.push(part);
        if std::fs::symlink_metadata(&ancestor).is_ok_and(|meta| meta.file_type().is_symlink()) {
            return false;
        }
    }
    true
}
